import axios from "axios";

// Base URL should point to the correct backend address
const API = axios.create({ baseURL: "http://localhost:3000" }); // Replace this if your backend uses another port

// Add Authorization header for protected routes
API.interceptors.request.use((req) => {
    const token = localStorage.getItem("token"); // Retrieve token from local storage
    if (token) {
        req.headers.Authorization = `Bearer ${token}`; // Attach token to the request header
    }
    return req; // Return the modified request
});

// Authentication APIs
export const loginUser = async ({ username, password }) => {
    try {
        // Make a POST request to the login endpoint
        const response = await API.post("/login", { username, password });
        return response.data; // Expected response: { token, user }
    } catch (error) {
        console.error("Login failed:", error.response?.data?.message || error.message);
        throw error; // Throw the error to handle it in the component
    }
};

// Franchise APIs
export const createFranchise = async (data) => {
    try {
        const response = await API.post("/franchises", data);
        return response.data; // Response contains created franchise details
    } catch (error) {
        console.error("Failed to create franchise:", error.response?.data?.message || error.message);
        throw error;
    }
};

export const getFranchises = async () => {
    try {
        const response = await API.get("/dashboard");
        return response.data; // Response contains the list of franchises
    } catch (error) {
        console.error("Failed to fetch franchises:", error.response?.data?.message || error.message);
        throw error;
    }
};

export const deleteFranchise = async (id) => {
    try {
        const response = await API.delete(`/franchises/${id}`);
        return response.data; // Response confirms successful deletion
    } catch (error) {
        console.error("Failed to delete franchise:", error.response?.data?.message || error.message);
        throw error;
    }
};

// User APIs
export const createUser = async (data) => {
    try {
        const response = await API.post("/users", data);
        return response.data; // Response contains created user details
    } catch (error) {
        console.error("Failed to create user:", error.response?.data?.message || error.message);
        throw error;
    }
};

export const updateExamData = async (franchiseId, data) => {
    try {
        const response = await API.put(`/franchises/${franchiseId}/exam-data`, data);
        return response.data; // Response contains updated franchise exam data
    } catch (error) {
        console.error("Failed to update exam data:", error.response?.data?.message || error.message);
        throw error;
    }
};
